public class CoinChangeGreedy {
    public int[] makeChange(int[] coins, int amount) {
        int[] result = new int[coins.length];
        for (int i = 0; i < coins.length; i++) {
            result[i] = amount / coins[i];
            amount %= coins[i];
        }
        return result;
    }
    public static void main(String[] args) {
        int[] coins = {25,10,5,1};
        int[] r = new CoinChangeGreedy().makeChange(coins, 67);
        for (int i=0; i<coins.length; i++) System.out.println(coins[i]+"¢: "+r[i]);
    }
}

